"""Undo, redo and history (docs/undo.md)."""

from binkeep import journal
from binkeep.bins import normalize
from binkeep.errors import DataError, Refused
from binkeep.report import entry_lines


def _broken(msg):
    return DataError("journal", msg)


def stacks(entries: list[dict]):
    """Reads the journal with the done and undone stacks (section 2).

    Returns (done, undone, dropped, ops) where ops lists every operation line."""
    done, undone, dropped, ops = [], [], set(), []
    for e in entries:
        op = e["op"]
        if op in journal.OPS:
            dropped.update(x["seq"] for x in undone)
            undone.clear()
            done.append(e)
            ops.append(e)
        elif op in ("undo", "redo"):
            src, dst = (done, undone) if op == "undo" else (undone, done)
            if not src or "target" not in e or src[-1]["seq"] != e["target"]:
                raise _broken(f"#{e['seq']}: {op} does not match the stacks")
            dst.append(src.pop())
    return done, undone, dropped, ops


def _qty_of(v, what):
    if not isinstance(v, int) or isinstance(v, bool):
        raise _broken(f"{what}: bad quantity")
    return v


def _plan_undo(ctx, op):
    """The (bin, delta-or-None, absolute) changes that take the operation back, as
    a list of (bin, function of current quantity -> new quantity)."""
    kind = op["op"]
    if kind == "fix":
        raise Refused("barrier", f"#{op['seq']} is a fix")
    try:
        if op.get("v") == 2:
            return [(normalize(x["bin"]), (lambda cur, b=x["before"]: b)) for x in reversed(op["effects"])]
        if kind == "count":
            raise Refused("irreversible", f"#{op['seq']} is a count without the old quantity")
        if kind == "receive":
            units = op["qty"]
            if op.get("uom") == "pk":
                if op["sku"] not in ctx.items:
                    raise _broken(f"#{op['seq']}: unknown item")
                units *= ctx.items[op["sku"]].pack_size
            return [(normalize(op["bin"]), lambda cur, u=units: cur - u)]
        if kind == "issue":
            return [(normalize(b), lambda cur, q=q: cur + q) for b, q in reversed(op["picks"])]
        if kind == "move":
            q = op["qty"]
            return [(normalize(op["to"]), lambda cur: cur - q), (normalize(op["from"]), lambda cur: cur + q)]
    except (KeyError, TypeError, ValueError):
        raise _broken(f"#{op['seq']}: malformed line") from None
    raise _broken(f"#{op['seq']}: malformed line")


def _plan_redo(undo_line):
    try:
        return [(normalize(x["bin"]), (lambda cur, b=x["before"]: b)) for x in reversed(undo_line["effects"])]
    except (KeyError, TypeError):
        raise _broken(f"#{undo_line['seq']}: malformed line") from None


def run(ctx, name: str, steps: int):
    """Carries out the steps on copies; returns the new store and the new lines."""
    store = ctx.store.copy()
    entries = list(ctx.entries)
    new = []
    for _ in range(steps):
        done, undone, _, _ = stacks(entries)
        if name == "undo":
            if not done:
                raise Refused("nothing-to-undo", "nothing to undo")
            op = done[-1]
            plan = _plan_undo(ctx, op)
        else:
            if not undone:
                raise Refused("nothing-to-redo", "nothing to redo")
            op = undone[-1]
            src = next((e for e in reversed(entries) if e["op"] == "undo" and e.get("target") == op["seq"]), None)
            if src is None:
                raise _broken(f"#{op['seq']}: no undo line")
            plan = _plan_redo(src)
        for code, _f in plan:
            if code not in ctx.bins:
                raise Refused("unknown-bin", f"no bin {code}")
        sku, effects = op["sku"], []
        for code, f in plan:
            before = store.qty(sku, code)
            after = _qty_of(f(before), f"#{op['seq']}")
            store.set(sku, code, after, restore=True)
            effects.append({"bin": code, "before": before, "after": after})
        e = journal.entry(journal.next_seq(entries), name, ctx.by, sku, target=op["seq"], effects=effects)
        entries.append(e)
        new.append(e)
    return store, new


def step_lines(e: dict, entries: list[dict]) -> list[str]:
    target = next(x for x in entries if x["seq"] == e["target"] and x["op"] in journal.OPS)
    lines = entry_lines(e)
    lines[0] += f" (#{e['target']} {target['op']})"
    return lines


def history(entries: list[dict], limit: int) -> list[str]:
    done, undone, dropped, ops = stacks(entries)
    done_ids = {id(x) for x in done}
    undone_ids = {id(x) for x in undone}
    out = []
    for o in reversed(ops[-limit:] if False else ops):
        if len(out) >= limit:
            break
        if o["op"] == "fix" and id(o) in done_ids:
            st = "barrier"
        elif id(o) in done_ids:
            st = "done"
        elif id(o) in undone_ids:
            st = "undone"
        else:
            st = "dropped"
        out.append(f"{o['seq']:>5}  {o['op']:<7}  {o.get('sku', ''):<10}  {st}")
    return out
